 1	// verifies
 2	// all bs are before all as which are before all ds
 3	predicate sortedbad(s:string) 
 4	{
 5	    // all b's are before all a's and d's
 6	    forall i,j :: 0 <= i < |s| && 0 <= j < |s| && s[i] == 'b' && (s[j] == 'a' || s[j] == 'd') ==> i < j &&
 7	    // all a's are after all b's
 8	    forall i,j :: 0 <= i < |s| && 0 <= j < |s| && s[i] == 'a' && s[j] == 'b' ==> i > j &&
 9	    // all a's are before all d's
10	    forall i,j :: 0 <= i < |s| && 0 <= j < |s| && s[i] == 'a' && s[j] == 'd' ==> i < j &&
11	    // all d's are after a;; b's and a's
12	    forall i,j :: 0 <= i < |s| && 0 <= j < |s| && s[i] == 'd' && (s[j] == 'a' || s[j] == 'b') ==> i > j
13	}
14	
15	method BadSort(a: string) returns (b: string)
16	requires forall k :: 0 <= k < |a| ==> a[k] == 'b' || a[k] == 'a' || a[k] == 'd';
17	ensures sortedbad(b);
18	ensures multiset(a[..]) == multiset(b[..]);
19	ensures |a| == |b|;
20	{
21	    b := a;
22	    var next := 0;
23	    var white := 0;
24	    var blue := |b|; // colours between next and blue unsorted
25	    while (next != blue) // if next==blue, no colours left to sort
26	    invariant forall k :: 0 <= k < |b| ==> b[k] == 'b' || b[k] == 'a' || b[k] == 'd';
27	    invariant 0 <= white <= next <= blue <= |b|;
28	    // ensure next, white, blue are correct
29	    invariant forall i :: 0 <= i < white ==> b[i] == 'b';
30	    invariant forall i :: white <= i < next ==> b[i] == 'a';
31	    // all b's are before all a's and d's
32	    invariant forall i,j :: 0 <= i < next && 0 <= j < next && b[i] == 'b' && (b[j] == 'a' || b[j] == 'd') ==> i < j
33	    // all a's are after all b's
34	    invariant forall i,j :: 0 <= i < next && 0 <= j < next && b[i] == 'a' && b[j] == 'b' ==> i > j
35	    // all a's are before all d's
36	    invariant forall i,j :: 0 <= i < next && 0 <= j < next && b[i] == 'a' && b[j] == 'd' ==> i < j
37	    // all d's are after a;; b's and a's
38	    invariant forall i,j :: 0 <= i < next && 0 <= j < next && b[i] == 'd' && (b[j] == 'a' || b[j] == 'b') ==> i > j
39	    invariant multiset(b[..]) == multiset(a[..]);
40	    invariant |a| == |b|;
41	    {   
42	        if b[next] == 'b' {
43	            var tmp := b[next];
44	            b := b[next := b[white]];
45	            b := b[white := tmp];
46	            next := next + 1;
47	            white := white + 1;
48	        } else if b[next] == 'a' {
49	            next := next + 1;
50	        } else if b[next] == 'd'{
51	            blue := blue - 1;
52	            var tmp := b[next];
53	            b := b[next := b[blue]];
54	            b := b[blue := tmp];
55	        } 
56	    }
57	}
58	method check() {
59	    var f:string := "dabdabdab";
60	    var g:string := BadSort(f);
61	    assert multiset(f)==multiset(g);
62	    assert sortedbad(g);
63	    /*
64	      f := "dba";          // testcase1
65	   g :=  BadSort(f);
66	   assert g=="bad";  
67	   f := "aaaaaaaa";    // testcase 2
68	   g :=  BadSort(f);
69	   assert g=="aaaaaaaa";
70	   */
71	   /*
72	    var a:string := "dabdabdab";
73	    var b:string := BadSort(a);
74	    assert multiset(a) == multiset(b);
75	    assert b == "bbbaaaddd";
76	    // apparently not possible ot verify this
77	    */
78	}
